import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as primitiveCreateNode } from '@/primitives';
import { createText as textCreate } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();
  root.name = config.name ?? 'CollectionNode';

  // ---------- Plane ----------
  const planeGeom = new PlaneGeometry(7, 6); // size arbitrary; will be scaled later if needed
  const planeMat = new MeshBasicNodeMaterial({ map: null, color: 0xffffff });
  const planeMesh = new Mesh(planeGeom, planeMat);
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // Load texture asynchronously
  let loadedTexture = null;
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    })
    .catch(() => {
      // texture load failure – keep material without map
    });

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    // Expect item.text and optionally typography.fontSize
    const fontSize = item.typography?.fontSize ?? 96;
    const textObj = ctx.fontAtlas.createText(item.text || '', {
      fontSize,
      color: config.visual?.colors?.paper || '#e8ecf2',
      align: 'center',
    });
    // Position text slightly above plane
    textObj.position.set(0, 0.8, 0.01);
    root.add(textObj);
  }

  // ---------- Cinematic Primitives ----------
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const instance = fn(root, prim.params ?? {});
        primitiveInstances.push(instance);
      }
    }
  }

  // ---------- UserData ----------
  root.userData.handlers = {}; // No interactions specified

  root.userData.cleanup = () => {
    // Dispose primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }

    // Dispose material and geometry
    planeMat.dispose();
    planeGeom.dispose();

    // Dispose texture if loaded
    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }

    // Kill any GSAP timelines (none created here, but guard)
    gsap.globalTimeline.clear();
  };

  // Return the prepared Object3D
  return root;
}
